import rolesData from "@/data/roles.json";
import type { CardData, Role } from "../types";
import { classify, isLand } from "./classify";

/**
 * Card roles from Scryfall Tagger (community-curated "oracle tags"), generated by
 * `npm run roles` into src/data/roles.json. Falls back to the oracle-text regexes in
 * classify.ts for cards the tagger hasn't covered (usually brand-new sets).
 * Server-only: the JSON is ~400 KB, so never import this from a client component.
 */

type RolesFile = { generatedAt: string; roles: Record<string, string[]> };
const data = rolesData as RolesFile;

const byName = new Map<string, Role[]>();
for (const [role, names] of Object.entries(data.roles)) {
  for (const n of names) {
    const k = n.toLowerCase();
    const list = byName.get(k) ?? [];
    list.push(role as Role);
    byName.set(k, list);
  }
}

/** When a card has several tags, the scarcer, more specific job wins. */
const PRIORITY: Role[] = ["wipe", "counter", "tutor", "ramp", "removal", "draw", "protection", "recursion"];

export const ROLES_GENERATED_AT = data.generatedAt;

export function tagRoles(name: string): Role[] {
  return byName.get(name.toLowerCase()) ?? byName.get(name.split(" // ")[0].toLowerCase()) ?? [];
}

export function classifyCard(c: CardData): { role: Role; source: "tag" | "text"; tags: Role[] } {
  if (isLand(c)) return { role: "land", source: "text", tags: [] };
  const tags = tagRoles(c.name);
  if (tags.length) {
    const role = PRIORITY.find((r) => tags.includes(r)) ?? tags[0];
    return { role, source: "tag", tags };
  }
  return { role: classify(c), source: "text", tags: [] };
}
